package com.envarg.signals;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.CookieManager;import org.json.*;import java.net.*;import java.io.*;import java.time.*;import java.time.format.*;
public class MonitorService extends Service {
 static final String CHANNEL="envarg-monitor",SIGNALS="envarg-signals";private Handler handler;private volatile boolean running=false;private String lastKey="";private volatile String monitorStatus="Starting…";
 @Override public void onCreate(){super.onCreate();NotificationManager m=getSystemService(NotificationManager.class);m.createNotificationChannel(new NotificationChannel(CHANNEL,"ENVARG Monitoring",NotificationManager.IMPORTANCE_LOW));m.createNotificationChannel(new NotificationChannel(SIGNALS,"ENVARG Signal Alerts",NotificationManager.IMPORTANCE_HIGH));handler=new Handler(Looper.getMainLooper());}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(!running){running=true;startForeground(100,base("ENVARG MONITOR ACTIVE","Checking verified signals every 30 seconds"));handler.post(loop);}return START_STICKY;}
 Notification base(String title,String body){PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_popup_sync).setContentTitle(title).setContentText(body).setContentIntent(pi).setOngoing(true).build();}
 private final Runnable loop=new Runnable(){public void run(){if(!running)return;new Thread(()->poll()).start();handler.postDelayed(this,30000);}};
 private void updateStatus(String message){monitorStatus=message;getSystemService(NotificationManager.class).notify(100,base("ENVARG MONITOR · "+message,"Background checks every 30s · not a live trade feed"));}
 private void poll(){try{String url="https://envarg-v9-signal.hatchable.site/api/auto-signals";String cookie=CookieManager.getInstance().getCookie("https://envarg-v9-signal.hatchable.site");HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");if(cookie!=null)c.setRequestProperty("Cookie",cookie);try(OutputStream out=c.getOutputStream()){out.write("{\"symbol\":\"EUR/USD\"}".getBytes("UTF-8"));}int http=c.getResponseCode();if(http!=200){c.disconnect();updateStatus(http==401||http==403?"LOGIN REQUIRED":"API ERROR "+http);return;}ByteArrayOutputStream buf=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1&&buf.size()<100000)buf.write(b,0,n);}c.disconnect();JSONObject j=new JSONObject(buf.toString("UTF-8"));String status=j.optString("status");if(status.equals("WAIT")){updateStatus("WAIT · NO VERIFIED CANDLES");return;}if(!status.equals("BUY")&&!status.equals("SELL")){updateStatus("NO VALID SIGNAL");return;}if(!j.optString("source").equals("verified imported historical data")){updateStatus("SOURCE NOT VERIFIED");return;}String key=j.optString("symbol")+"|"+j.optString("candleOpen");if(key.equals(lastKey))return;String expiry=j.optString("expiresAt");if(!expiry.isEmpty()&&Instant.parse(expiry).isBefore(Instant.now())){updateStatus("SIGNAL EXPIRED");return;}lastKey=key;updateStatus("VERIFIED RESEARCH SIGNAL");String dir=status.equals("BUY")?"UP":"DOWN";String time=ZonedDateTime.now(ZoneId.of("Asia/Kolkata")).format(DateTimeFormatter.ofPattern("dd MMM yyyy hh:mm:ss a"));Notification n=new Notification.Builder(this,SIGNALS).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("ENVARG "+dir+" SIGNAL · "+j.optString("symbol")).setContentText(time+" IST · Research only").setStyle(new Notification.BigTextStyle().bigText("SIGNAL: "+dir+"\nPAIR: "+j.optString("symbol")+"\nTIME: "+time+" IST\nResearch only. Not a trade instruction.")).setAutoCancel(true).build();getSystemService(NotificationManager.class).notify(200+(int)(System.currentTimeMillis()%10000),n);}catch(Exception e){updateStatus("NETWORK OR LOGIN ERROR");}}
 @Override public void onDestroy(){running=false;handler.removeCallbacks(loop);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
